import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const r="/assets/kotak_1.Bz7UuwSV.PNG",s="/assets/kotak_2.DRRZbqZc.PNG",n="/assets/image%20(2)%20(1).Dgnfd5e-.png",l="/assets/image%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1).CFR3_I_3.png",c="/assets/image%20(2)%20(1)%20(1).0_h27JJJ.png",p="/assets/image%20(3).C7RfzEVA.png",P=JSON.parse('{"title":"Kotak Securities","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/kotak-securities.md","filePath":"connect-brokers/brokers/kotak-securities.md"}'),d={name:"connect-brokers/brokers/kotak-securities.md"};function g(u,e,h,f,m,k){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="kotak-securities" tabindex="-1">Kotak Securities <a class="header-anchor" href="#kotak-securities" aria-label="Permalink to &quot;Kotak Securities&quot;">​</a></h1><p>Kotak Securities is a prominent Indian stock broker offering services on major Indian stock exchanges, including NSE, BSE, and MCX. Known for its comprehensive financial services and advanced trading solutions, Kotak Securities provides a robust platform for traders and investors. By leveraging Kotak&#39;s Trading APIs, developers and algo traders can seamlessly integrate their trading strategies with the Tradeboard platform.</p><p>For developers and algo traders looking to use the Kotak API, the integration process generally involves the following steps:</p><h3 id="step-by-step-integration" tabindex="-1">Step-by-Step Integration <a class="header-anchor" href="#step-by-step-integration" aria-label="Permalink to &quot;Step-by-Step Integration&quot;">​</a></h3><h4 id="step-1-prepare-your-trading-credentials" tabindex="-1">Step 1: Prepare Your Trading Credentials <a class="header-anchor" href="#step-1-prepare-your-trading-credentials" aria-label="Permalink to &quot;Step 1: Prepare Your Trading Credentials&quot;">​</a></h4><p>Ensure you have your Kotak Securities Trading User ID and Password ready.</p><h4 id="step-2-register-for-api-access" tabindex="-1">Step 2: Register for API Access <a class="header-anchor" href="#step-2-register-for-api-access" aria-label="Permalink to &quot;Step 2: Register for API Access&quot;">​</a></h4><ol><li>Navigate to the <a href="https://neo.kotaksecurities.com/" target="_blank" rel="noreferrer">Kotak Securities API registration page.</a> login with your trading credentials</li><li>Navigate to: More</li></ol><figure><img src="'+r+'" alt=""><figcaption></figcaption></figure><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><ol><li>Click &quot;Create Application&quot;</li><li>Copy the token shown after creation</li></ol><p><strong>Token format example</strong>: ec6a746c-e44b-455e-abf2-c13352b2fc45</p><h4 id="step-3-register-totp-authentication" tabindex="-1"><strong>Step 3: Register TOTP Authentication</strong> <a class="header-anchor" href="#step-3-register-totp-authentication" aria-label="Permalink to &quot;**Step 3: Register TOTP Authentication**&quot;">​</a></h4><p>Register for TOTP from the Menu Section</p><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><p><strong>What is TOTP?</strong> Time-based One-Time Password generates a new 6-digit code every 30 seconds in an authenticator app. This is your dynamic password for API login.</p><p><strong>Steps:</strong></p><ol><li>In API Dashboard, click <strong>&quot;TOTP Registration&quot;</strong></li><li>Verify with your mobile number and OTP</li><li>Download <strong>Google Authenticator</strong> or <strong>Microsoft Authenticator</strong> from app store</li><li>Scan the QR code displayed on screen</li><li>Enter the 6-digit TOTP code shown in the authenticator app</li><li>Confirm when you see &quot;TOTP successfully registered&quot;</li></ol><p>Example:</p><ol><li>TOTP Registration screen: on verification of mobile number, otp and client code</li></ol><figure><img src="'+l+'" alt=""><figcaption></figcaption></figure><ol start="2"><li>Scan QR from authenticator app, Enter these 6 digits reflecting on authenticator app for Kotak-NEO, and click continue. You will get success toast which means registration of totp is complete.</li></ol><figure><img src="'+c+'" alt=""><figcaption></figcaption></figure><h4 id="step-4-find-your-ucc-client-code" tabindex="-1">Step 4: Find Your UCC (Client Code) <a class="header-anchor" href="#step-4-find-your-ucc-client-code" aria-label="Permalink to &quot;Step 4: Find Your UCC (Client Code)&quot;">​</a></h4><ol><li>Go to NEO app/web Profile section</li><li>Your UCC is displayed as &quot;Client Code&quot;</li><li>Format: 5 characters (e.g., &quot;AB123&quot;)</li></ol><figure><img src="'+p+`" alt=""><figcaption></figcaption></figure><h4 id="step-5-your-6-digit-mpin" tabindex="-1">Step 5 : Your 6-digit MPIN <a class="header-anchor" href="#step-5-your-6-digit-mpin" aria-label="Permalink to &quot;Step 5 : Your 6-digit MPIN&quot;">​</a></h4><ul><li>This is your trading PIN used to authorize orders in NEO app</li><li>You use the same MPIN for API authentication</li></ul><p><strong>If you don&#39;t remember it:</strong></p><ul><li>NEO app &gt; Profile &gt; Settings &gt; Change MPIN</li></ul><h4 id="retrieve-api-credentials" tabindex="-1">Retrieve API Credentials: <a class="header-anchor" href="#retrieve-api-credentials" aria-label="Permalink to &quot;Retrieve API Credentials:&quot;">​</a></h4><ul><li>Copy the Unique Client Code as Format: 5 characters (e.g., &quot;AB123&quot;) , which will be your API Key.</li><li>Copy the Token generated from step 2 as Token format example: ec6a746c-e44b-455e-abf2-c13352b2fc45, which will serve as your API Secret</li></ul><h3 id="configuration" tabindex="-1">Configuration: <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration:&quot;">​</a></h3><p>Set up your environment variables in a <code>.env</code> file for Kotak&#39;s API:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BROKER_API_KEY = &#39;your_kotak_unique_client_code&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_kotak_token_generated&#39;</span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/kotak/callback&#39;</span></span></code></pre></div><p>Integrating with the Kotak API opens up new possibilities for implementing automated and algorithmic trading strategies. It provides developers and traders with a robust platform to access market opportunities efficiently and effectively. To fully leverage the capabilities of the Kotak API, it is essential to follow best practices for API integration. This includes careful management of API rate limits, secure handling of API keys, and thorough error handling and logging. These practices help ensure a dependable and optimal trading experience using Kotak&#39;s advanced technological infrastructure.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/kotak/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,39)])])}const _=t(d,[["render",g]]);export{P as __pageData,_ as default};
